const ACCOUNT_BY_CODE = {};
ACCOUNT_CATALOG.forEach(([group, code, name, dep, expCode, expName]) => {
  ACCOUNT_BY_CODE[code] = { group, code, name, depreciable: dep, expCode, expName };
});
/** The 3 "Construction in Progress" cost account codes — CIP projects (tracked in their own
 *  section, separate from the Asset Register) live under these, and a CIP project's running
 *  total still counts toward these accounts' cost in Reconciliation until it's capitalized. */
const CIP_ACCOUNT_CODES = ACCOUNT_CATALOG.filter(([g]) => g === "Construction in Progress").map(([, code]) => code);
function isCipAccount(code) { return CIP_ACCOUNT_CODES.includes(Number(code)); }

/** Acquisition types an Asset Register / CIP-transfer entry can record, beyond a normal
 *  purchase — request was "not only acquired item but also found at the station and donated
 *  items received". Missing/undefined on an existing asset doc means "purchased" (no
 *  migration needed for the records already in production). */
const ACQUISITION_TYPES = [
  { code: "purchased", label: "Purchased / acquired" },
  { code: "found", label: "Found at the station" },
  { code: "donated", label: "Donated" },
];
function acquisitionTypeLabel(code) { return (ACQUISITION_TYPES.find(t => t.code === code) || ACQUISITION_TYPES[0]).label; }
/** Looks up an account code in EITHER catalog — the PPE catalog (ACCOUNT_BY_CODE, defined above)
 *  or the Semi-Expendable catalog (SX_ACCOUNT_BY_CODE, defined further down in the SX section) —
 *  since PPE and Semi-Expendable items now live together in one register, one lookup needs to
 *  recognize both. The two code ranges never overlap (107xxx/108xxx/109xxx for PPE vs
 *  10405xxx/10406xxx for Semi-Expendable), so there's no ambiguity. A Semi-Expendable account is
 *  never `depreciable` (that catalog never sets it), which is what lets every existing
 *  depreciation/reconciliation function below keep working unchanged once Semi-Expendable items
 *  share the same `assets` collection — they fall through the same "n/a, not depreciable" paths
 *  already used for Land/CIP/Biological PPE accounts. */
function accountInfo(code) {
  return ACCOUNT_BY_CODE[code] || SX_ACCOUNT_BY_CODE[code] || { group: "Other", code, name: "Account " + code, depreciable: false, expCode: null, expName: null };
}
/** True if this account code belongs to the Semi-Expendable catalog specifically — used where PPE
 *  and Semi-Expendable need different treatment despite sharing the register (e.g. excluding
 *  Semi-Expendable accounts from the Trial-Balance-tie-out gate that unlocks PPE depreciation
 *  posting, since Semi-Expendable has no posting workflow of its own to protect). */
function isSxAccount(code) { return Object.prototype.hasOwnProperty.call(SX_ACCOUNT_BY_CODE, code); }
/** "ppe" or "sx" — defaults to "ppe" for any asset saved before this field existed (the 245
 *  production assets included), so no data migration is needed. */
function itemTypeOf(asset) { return asset && asset.item_type === "sx" ? "sx" : "ppe"; }
/** Sentinel value for the Accountable Officer filter's "no officer assigned" option — distinct
 *  from "" (which means "all officers, no filter") and from any real officer name, so items with
 *  a blank accountable_officer can be filtered to specifically rather than being unreachable. */
const NO_OFFICER = "__no_officer__";

const BASELINE_PERIOD = "2025-12"; // last closed year-end this registry is anchored to (per uploaded TB)

// Municipal seal, embedded as a data: URI so the printed Equipment Ledger Card / Property Card
// work with no external image request. Paste a "data:image/png;base64,...." string here (export
// your seal as a PNG and base64-encode it) to have it appear in the card header; leave blank to
// print a clean text-only header instead.
const MUNICIPAL_SEAL_DATA_URI = "data:image/jpeg;base64,";
// Funds tracked by this registry. Every asset belongs to exactly one; missing/undefined on an
// asset or a postings/tb_snapshots doc always means "GF" (so the 245 assets and history already
// in production, seeded before Funds existed, keep working with no data migration required).
const FUNDS = [
  { code: "GF", label: "General Fund" },
  { code: "SEF", label: "Special Education Fund" },
  { code: "TF", label: "Trust Fund" },
];
function fundInfo(code) { return FUNDS.find(f => f.code === code) || FUNDS[0]; }
function fundLabel(code) { return fundInfo(code).label; }
/** Firestore doc ID for a (fund, period) pair in postings/tb_snapshots. GF keeps the original
 *  plain-period ID scheme (e.g. "2026-01") so existing production docs need no migration; SEF/TF
 *  get a composite ID (e.g. "SEF__2026-01") since a GF doc may already own the plain period ID. */
function fundDocId(fund, period) { return fund === "GF" ? period : `${fund}__${period}`; }

/* ---------- Generic helpers ---------- */
const PESO = new Intl.NumberFormat("en-PH", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
function fmtMoney(n) { n = Number(n) || 0; return (n < 0 ? "-Php " : "Php ") + PESO.format(Math.abs(n)); }
function fmtNum(n) { return PESO.format(Number(n) || 0); }
function round2(n) { return Math.round((Number(n) || 0) * 100) / 100; }
function esc(s) { return String(s == null ? "" : s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c])); }
function fmtDate(d) {
  if (!d) return "—";
  const dt = new Date(d + "T00:00:00");
  if (isNaN(dt)) return d;
  return dt.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
}
const MONTH_NAMES = ["January","February","March","April","May","June","July","August","September","October","November","December"];
function periodLabel(p) { const [y, m] = p.split("-").map(Number); return MONTH_NAMES[m - 1] + " " + y; }
function periodShort(p) { const [y, m] = p.split("-").map(Number); return MONTH_NAMES[m - 1].slice(0,3) + " " + y; }
function addMonths(p, n) {
  let [y, m] = p.split("-").map(Number);
  m += n;
  y += Math.floor((m - 1) / 12);
  m = ((m - 1) % 12 + 12) % 12 + 1;
  return y + "-" + String(m).padStart(2, "0");
}
function cmpPeriod(a, b) { return a < b ? -1 : a > b ? 1 : 0; }
function todayPeriod() {
  const d = new Date();
  return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0");
}
function csvField(v) {
  v = v == null ? "" : String(v);
  if (/[",\n]/.test(v)) return '"' + v.replace(/"/g, '""') + '"';
  return v;
}
function toast(msg) {
  const t = document.getElementById("toast");
  t.textContent = msg;
  t.classList.add("show");
  clearTimeout(toast._t);
  toast._t = setTimeout(() => t.classList.remove("show"), 2600);
}
function uid(prefix) { return prefix + "_" + Date.now().toString(36) + Math.random().toString(36).slice(2, 7); }

/* ---------- App state ---------- */
const S = {
  db: null,
  ready: false,
  assets: new Map(),      // id -> asset doc
  postings: new Map(),    // period -> {period, amounts:{}, postedAt, postedBy}
  tbSnapshots: new Map(), // period -> {period, accounts:{}, ...}
  cipProjects: new Map(), // id -> CIP project doc (own collection, separate from assets)
  parIcs: new Map(),      // id -> PAR/ICS record doc (own collection, separate from assets — a
                           // "pending" one is a parking record, not yet in the Asset Register)
  ptrItr: new Map(),      // id -> PTR/ITR record doc (own collection) — generated automatically by
                           // transferAsset() every time an item's location/accountable officer is
                           // transferred; unlike PAR/ICS there's no pending/recorded lifecycle here,
                           // since the transfer itself already happened — see the PTR/ITR section.
  linkParIcsId: null,     // set by recordParIcsAsNew() right before opening the Add Item modal — tells
                           // saveAsset() which pending PAR/ICS record to mark "recorded" once the
                           // new asset is created. Reset to null at the top of every openAssetModal()
                           // call (via its `prefill.parIcsId`), so it never leaks into an unrelated add.
  view: "dashboard",
  currentFund: "GF",      // which fund's books are currently in view — set by setFund(), restored from localStorage
  currentUser: null,      // Firebase Auth user, set by initApp()
  // itemType filters which item(s) show: "" (all), "ppe", or "sx" — PPE and Semi-Expendable items
  // live together in one register per fund, tagged by item_type, rather than in separate sections.
  registerFilter: { q: "", category: "", status: "active", itemType: "", classification: "" },
  reportsFilter: { q: "", category: "", status: "active", officer: "", itemType: "", classification: "" },
  cipFilter: { q: "", status: "in_progress" },
  parIcsFilter: { q: "", docType: "", status: "pending" },
  ptrItrFilter: { q: "", docType: "" },
  depPeriod: null,   // chosen period for Monthly Depreciation view
  reconPeriod: null, // chosen period for Reconciliation view
  reconDraft: "",    // unsaved Trial Balance text (pasted or uploaded) not yet tied to a saved period
};
/** Label used for "last edited by" / "posted by" style attribution — the signed-in user's email. */
function viewerLabel() {
  return (S.currentUser && (S.currentUser.email || S.currentUser.displayName)) || "Unnamed";
}

/* ---------- Depreciation engine ---------- */
function monthlyRate(asset) {
  if (!asset.depreciable || !asset.useful_life_years) return 0;
  const base = (asset.cost || 0) - (asset.residual_value || 0);
  const months = asset.useful_life_years * 12;
  if (months <= 0) return 0;
  return base / months;
}
function acquiredMonth(asset) {
  if (!asset.date_acquired) return null;
  return asset.date_acquired.slice(0, 7);
}
/** Sum of all posted depreciation for one asset across every posted period (any fund — an asset
 *  only ever appears in the postings of its own fund's posting runs, so this needs no fund filter). */
function postedTotalFor(assetId) {
  let sum = 0;
  for (const doc of S.postings.values()) {
    if (doc.amounts && doc.amounts[assetId]) sum += doc.amounts[assetId];
  }
  return sum;
}
/** Sum of posted depreciation for one asset, periods <= given period (inclusive), period > baseline.
 *  Compares each doc's own `period` field rather than its Firestore doc ID, since SEF/TF postings
 *  use a composite doc ID (see fundDocId) that isn't itself a comparable "YYYY-MM" period string. */
function postedTotalThrough(assetId, period) {
  let sum = 0;
  for (const doc of S.postings.values()) {
    if (doc.amounts && doc.amounts[assetId] && cmpPeriod(doc.period, period) <= 0) sum += doc.amounts[assetId];
  }
  return sum;
}
function currentAccumDepr(asset) {
  return round2((asset.accum_depr_baseline || 0) + postedTotalFor(asset.id));
}
function accumDeprAsOf(asset, period) {
  if (cmpPeriod(period, BASELINE_PERIOD) <= 0) return round2(asset.accum_depr_baseline || 0);
  return round2((asset.accum_depr_baseline || 0) + postedTotalThrough(asset.id, period));
}
function carryingAmount(asset, period) {
  const ad = period ? accumDeprAsOf(asset, period) : currentAccumDepr(asset);
  return round2((asset.cost || 0) - ad);
}
/** Depreciation amount that WOULD post for `period` for this asset, given everything posted before it. */
function previewAmountFor(asset, period) {
  if (asset.status !== "active" || !asset.depreciable) return 0;
  if (cmpPeriod(period, BASELINE_PERIOD) <= 0) return 0;
  const am = acquiredMonth(asset);
  if (am && cmpPeriod(period, am) <= 0) return 0; // depreciation starts the month AFTER acquisition
  const rate = monthlyRate(asset);
  if (rate <= 0) return 0;
  const alreadyBefore = round2((asset.accum_depr_baseline || 0) + postedTotalThrough(asset.id, addMonths(period, -1)));
  const depreciableBase = (asset.cost || 0) - (asset.residual_value || 0);
  const remaining = round2(depreciableBase - alreadyBefore);
  if (remaining <= 0.004) return 0;
  return round2(Math.min(rate, remaining));
}
/** All postings docs belonging to one fund (missing `fund` field on a doc means GF — see FUNDS above). */
function postingsForFund(fund) { return [...S.postings.values()].filter(doc => (doc.fund || "GF") === fund); }
/** All tb_snapshots docs belonging to one fund. */
function tbSnapshotsForFund(fund) { return [...S.tbSnapshots.values()].filter(doc => (doc.fund || "GF") === fund); }
function getPosting(fund, period) { return postingsForFund(fund).find(d => d.period === period) || null; }
function getTbSnapshot(fund, period) { return tbSnapshotsForFund(fund).find(d => d.period === period) || null; }
/** Next period that has not yet been posted, for one fund's own posting history. */
function nextUnpostedPeriod(fund) {
  const posted = new Set(postingsForFund(fund).map(d => d.period));
  let p = addMonths(BASELINE_PERIOD, 1);
  while (posted.has(p)) p = addMonths(p, 1);
  return p;
}
function lastPostedPeriod(fund) {
  let last = null;
  postingsForFund(fund).forEach(d => { if (!last || cmpPeriod(d.period, last) > 0) last = d.period; });
  return last;
}
function activeAssets(fund) { return [...S.assets.values()].filter(a => a.status === "active" && (a.fund || "GF") === fund); }
function depreciableActiveAssets(fund) { return activeAssets(fund).filter(a => a.depreciable); }

/* ---------- CIP (Construction in Progress) engine ----------
   CIP projects are tracked in their own collection/section, separate from the Asset Register —
   each accumulates multiple contractor billings over the life of a project before eventually
   being "completed" (capitalized) into a regular PPE asset. Until that happens, an in-progress
   project's running total still needs to show up wherever its account code (one of
   CIP_ACCOUNT_CODES) is reconciled against the Trial Balance, exactly as if it were still one
   register row — see distinctCostAccounts/registryCostFor below. */
function cipProjectsInFund(fund) { return [...S.cipProjects.values()].filter(p => (p.fund || "GF") === fund); }
/** In-progress (not yet transferred/capitalized) CIP projects for a fund — these are the ones
 *  whose cost still needs to reconcile against the Trial Balance under their CIP account code. */
function activeCipProjects(fund) { return cipProjectsInFund(fund).filter(p => p.status !== "completed"); }
function cipBillingTotal(b) {
  return round2((Number(b.by_contract) || 0) + (Number(b.admin_materials) || 0) + (Number(b.admin_labor) || 0) +
    (Number(b.admin_overhead) || 0) + (Number(b.admin_consultancy) || 0) + (Number(b.admin_others) || 0) +
    (Number(b.transfers_adjustments) || 0));
}
function cipProjectTotal(p) { return round2((p.billings || []).reduce((s, b) => s + cipBillingTotal(b), 0)); }

/** True once any billing on this project reads as a final one (its ref/particulars/remarks
 *  mentions "final" — matches how these billings are actually labeled in practice, e.g. "2ND &
 *  FINAL BILLING"). Used to auto-flag a project as physically finished/awaiting transfer without
 *  requiring anyone to click a button — including projects whose billings were bulk-imported
 *  before this existed, since it's computed from the billing text rather than a stored flag. */
function cipHasFinalBilling(p) {
  const re = /\bfinal\b/i;
  return (p.billings || []).some(b => re.test(b.ref || "") || re.test(b.particulars || "") || re.test(b.remarks || ""));
}
/** The project's real status for display/filtering — three states: "in_progress", "finished"
 *  (construction done, awaiting capitalization — auto-detected from a final billing, or set/
 *  cleared manually via `status_override`), and "completed" (transferred to a PPE asset — the
 *  one status value ever written by completeCipProject(), and always authoritative once set). */
function effectiveCipStatus(p) {
  if (p.status === "completed") return "completed";
  if (p.status_override) return p.status_override;
  return cipHasFinalBilling(p) ? "finished" : "in_progress";
}
function cipStatusPill(status) {
  if (status === "completed") return '<span class="pill neutral">Transferred</span>';
  if (status === "finished") return '<span class="pill warn">Complete</span>';
  return '<span class="pill good">In progress</span>';
}
function cipStatusLabel(status) {
  return status === "completed" ? "Transferred" : status === "finished" ? "Complete (awaiting transfer)" : "In progress";
}

/* ---------- Reconciliation engine ---------- */
/** distinct {code,name} cost accounts actually used in one fund's active register, sorted by
 *  code — includes CIP account codes with an in-progress project even though those projects no
 *  longer live in the Asset Register itself, so Reconciliation keeps covering them. Items with no
 *  account code at all (e.g. undocumented "found at the station" items awaiting classification)
 *  are deliberately excluded here — there's no code to reconcile against, and including them used
 *  to add a bogus "null" row to the Reconciliation table. Their cost still counts in Dashboard/
 *  Register/Reports totals; they're just outside what Reconciliation can check. */
function distinctCostAccounts(fund) {
  const map = new Map();
  activeAssets(fund).forEach(a => { if (a.account_code && !map.has(a.account_code)) map.set(a.account_code, a.account_name); });
  activeCipProjects(fund).forEach(p => { if (p.account_code && !map.has(p.account_code)) map.set(p.account_code, p.account_name); });
  return [...map.entries()].sort((a, b) => a[0] - b[0]).map(([code, name]) => ({ code, name }));
}
function registryCostFor(code, fund) {
  const assetCost = round2(activeAssets(fund).filter(a => a.account_code === code).reduce((s, a) => s + (a.cost || 0), 0));
  const cipCost = round2(activeCipProjects(fund).filter(p => p.account_code === code).reduce((s, p) => s + cipProjectTotal(p), 0));
  return round2(assetCost + cipCost);
}
function registryADFor(code, period, fund) {
  return round2(activeAssets(fund).filter(a => a.account_code === code && a.depreciable)
    .reduce((s, a) => s + accumDeprAsOf(a, period), 0));
}
/** Build the full variance table for a chosen fund+period against that fund's tb_snapshot doc (or null). */
function computeReconciliation(fund, period) {
  const tb = getTbSnapshot(fund, period);
  const accounts = tb ? tb.accounts : null;
  return distinctCostAccounts(fund).map(({ code, name }) => {
    const adCode = code + 1;
    const regCost = registryCostFor(code, fund);
    const regAD = registryADFor(code, period, fund);
    const tbCost = accounts && accounts[code] ? Number(accounts[code].debit || 0) : null;
    const tbAD = accounts && accounts[adCode] ? Number(accounts[adCode].credit || 0) : null;
    const varCost = tbCost == null ? null : round2(regCost - tbCost);
    const varAD = tbAD == null ? null : round2(regAD - tbAD);
    // Trial Balance exports commonly omit a line entirely when its balance is zero, rather than
    // listing it as 0 — so a missing AD line only counts against reconciliation if the register
    // itself shows a nonzero accumulated depreciation for that account (a real, unexplained gap).
    // A missing AD line paired with Php 0.00 register AD (e.g. an asset that hasn't started
    // depreciating yet) is not a variance worth flagging.
    const adOk = !accountInfo(code).depreciable || (tbAD != null ? Math.abs(varAD) < 1 : Math.abs(regAD) < 1);
    const ok = tbCost != null && Math.abs(varCost) < 1 && adOk;
    return { code, name, adCode, regCost, regAD, tbCost, tbAD, varCost, varAD, ok, hasTb: !!accounts };
  });
}
/**
 * Is the PPE cost (not accumulated depreciation) side of the register tied out to a Trial
 * Balance for the month immediately before the given depreciation period? This is the gate we
 * check before letting a period be posted — accumulated depreciation isn't checked here since
 * this period's posting is exactly what would change it. This deliberately requires the
 * *immediately preceding* month's Trial Balance specifically (not just "some Trial Balance at or
 * before this period") — posting July depreciation off a stale May snapshot, with June's
 * Reconciliation never entered, is exactly the gap this closes.
 */
function costReconciliationStatus(fund, period) {
  const requiredPeriod = addMonths(period, -1);
  const hasRequired = tbSnapshotsForFund(fund).some(d => d.period === requiredPeriod);
  if (!hasRequired) return { ok: false, reason: "no-tb", tbPeriod: null, requiredPeriod, flagged: [] };
  // Excludes Semi-Expendable cost accounts — this gate exists to protect PPE depreciation
  // posting specifically, and Semi-Expendable has no posting workflow of its own to protect, so
  // an unrelated Semi-Expendable inventory-account variance shouldn't block PPE depreciation.
  const rows = computeReconciliation(fund, requiredPeriod).filter(r => distinctCostAccounts(fund).some(c => c.code === r.code) && !isSxAccount(r.code));
  const flagged = rows.filter(r => r.tbCost == null || Math.abs(r.varCost) >= 1);
  return { ok: flagged.length === 0, reason: flagged.length ? "variance" : null, tbPeriod: requiredPeriod, requiredPeriod, flagged };
}

/* ---------- JEV (journal entry voucher) engine ---------- */
/** Grouped debit/credit lines for one fund's period depreciation — posted if it exists, else a live preview. */
function jevForPeriod(fund, period) {
  const posted = getPosting(fund, period);
  const lines = new Map(); // expCode -> {expCode,expName,adCode,adName,amount}
  if (posted) {
    for (const [assetId, amt] of Object.entries(posted.amounts || {})) {
      const asset = S.assets.get(assetId);
      if (!asset || !amt) continue;
      addJevLine(lines, asset, amt);
    }
  } else {
    depreciableActiveAssets(fund).forEach(a => {
      const amt = previewAmountFor(a, period);
      if (amt > 0) addJevLine(lines, a, amt);
    });
  }
  const arr = [...lines.values()].sort((a, b) => a.expCode - b.expCode);
  const total = round2(arr.reduce((s, l) => s + l.amount, 0));
  return { posted: !!posted, lines: arr, total, postedAt: posted && posted.postedAt, postedBy: posted && posted.postedBy };
}
function addJevLine(lines, asset, amt) {
  const info = accountInfo(asset.account_code);
  const key = asset.account_code;
  if (!lines.has(key)) {
    lines.set(key, {
      expCode: info.expCode || asset.dep_exp_account_code, expName: info.expName || asset.dep_exp_account_name,
      adCode: asset.account_code + 1, adName: "Accumulated Depreciation - " + info.name, amount: 0,
    });
  }
  lines.get(key).amount = round2(lines.get(key).amount + amt);
}

/* ---------- DB init (Firestore, via the js/firebase.js adapter) ---------- */
function initDb() {
  try {
    S.db = db;
    db.collection("assets").onSnapshot(
      snap => { S.assets.clear(); snap.docs.forEach(d => S.assets.set(d.id, { id: d.id, ...d.data() })); S.ready = true; setSync(true); renderAll(); },
      err => { console.error(err); setSync(false, "Connection issue — showing last known data."); }
    );
    db.collection("postings").onSnapshot(
      snap => { S.postings.clear(); snap.docs.forEach(d => S.postings.set(d.id, d.data())); renderAll(); },
      err => console.error(err)
    );
    db.collection("tb_snapshots").onSnapshot(
      snap => { S.tbSnapshots.clear(); snap.docs.forEach(d => S.tbSnapshots.set(d.id, d.data())); renderAll(); },
      err => console.error(err)
    );
    db.collection("cip_projects").onSnapshot(
      snap => { S.cipProjects.clear(); snap.docs.forEach(d => S.cipProjects.set(d.id, { id: d.id, ...d.data() })); renderAll(); },
      err => console.error(err)
    );
    db.collection("par_ics").onSnapshot(
      snap => { S.parIcs.clear(); snap.docs.forEach(d => S.parIcs.set(d.id, { id: d.id, ...d.data() })); renderAll(); },
      err => console.error(err)
    );
    db.collection("ptr_itr").onSnapshot(
      snap => { S.ptrItr.clear(); snap.docs.forEach(d => S.ptrItr.set(d.id, { id: d.id, ...d.data() })); renderAll(); },
      err => console.error(err)
    );
    // Semi-Expendable Property items live in this same "assets" collection (tagged item_type:
    // "sx") and Trial Balance snapshots in this same "tb_snapshots" collection — see the
    // item_type unification above — so no separate sx_assets/sx_tb_snapshots listeners are needed.
  } catch (e) {
    console.error(e);
    setSync(false, "Database unavailable — check your Firebase configuration.");
  }
}
function setSync(live, msg) {
  document.getElementById("syncdot").classList.toggle("live", !!live);
  document.getElementById("syncstatus").textContent = msg || (live ? "Live — synced with your team" : "Offline");
}

